const rows = $input.all();
const newRows = rows.filter(item =>
  (item.json.STATUS || '').toString().trim().toLowerCase() === 'new'
);
if (newRows.length === 0) throw new Error('No rows with STATUS = "New" found in the Ideas sheet.');
const displayRows = newRows.slice(0, 10);
const topicList = displayRows.map((item, i) => `${i + 1}. ${item.json.TOPIC || '(no topic)'}`).join('\n');
return [{ json: { topicList, allRows: JSON.stringify(displayRows.map(r => r.json)), count: displayRows.length } }];

const selection = parseInt($json['CASE NUMBER'], 10);
const allRows   = JSON.parse($('Aggregate Topics').first().json.allRows);
if (!selection || selection < 1 || selection > allRows.length)
  throw new Error(`Invalid selection "${selection}". Enter 1–${allRows.length}.`);
const row  = allRows[selection - 1];
const ts   = new Date().toISOString().replace(/[^0-9]/g, '').substring(0, 12);
const slug = (row.TOPIC || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').substring(0, 45) + '_' + ts;
return [{
  json: {
    topic:      row.TOPIC || '',
    audience:   'curious history fans, conspiracy-adjacent adults 25–45',
    runtime:    20,
    slug,
    projectDir: '/Users/jneal/n8n_projects/' + slug
  }
}];

const fs   = require('fs');
const path = require('path');
let vars;
try { vars = $('Look Up Selected Row').first().json; } catch(e) { vars = $('Webhook Topic Setup').first().json; }

const dirs = ['scripts','audio','images','videos','clips','music','sfx'];
fs.mkdirSync(vars.projectDir, { recursive: true });
for (const d of dirs) {
  fs.mkdirSync(path.join(vars.projectDir, d), { recursive: true });
}

console.log('Directories created: ' + vars.projectDir);
return [{ json: vars }];

const fs   = require('fs');
const vars = $input.first().json;
const sys  = fs.readFileSync('/Users/jneal/n8n_projects/ruins_untold_system_prompts/research_agent.md', 'utf-8');
const userInput = JSON.stringify({ topic: vars.topic, audience: vars.audience, runtime: vars.runtime }, null, 2);
const prompt = sys + '\n\n---\n\nYour input:\n\n' + userInput;
return [{ json: { ...vars, claudeBody: JSON.stringify({ prompt }) } }];

const fs   = require('fs');
const inp  = $input.first().json;
const vars = $('Build Research Prompt').first().json;
if (inp.exitCode !== undefined && inp.exitCode !== 0)
  throw new Error('Claude bridge error: ' + inp.error);
let raw = (inp.output || '').trim();
const m = raw.match(/```(?:json)?\n?([\s\S]*?)```/);
if (m) raw = m[1].trim();
let pkg;
try { pkg = JSON.parse(raw); }
catch (e) {
  const s = raw.indexOf('{'), en = raw.lastIndexOf('}');
  if (s === -1 || en === -1) throw new Error('Cannot parse research_package.json. Raw output:\n' + raw.substring(0, 300));
  pkg = JSON.parse(raw.substring(s, en + 1));
}
const outPath = vars.projectDir + '/scripts/research_package.json';
fs.writeFileSync(outPath, JSON.stringify(pkg, null, 2), 'utf-8');
// Pass only project vars — research_package.json is on disk
return [{ json: { topic: vars.topic, audience: vars.audience, runtime: vars.runtime, slug: vars.slug, projectDir: vars.projectDir } }];

const fs   = require('fs');
const vars = $input.first().json;
const sys  = fs.readFileSync('/Users/jneal/n8n_projects/ruins_untold_system_prompts/script_agent.md', 'utf-8');
const researchJson = fs.readFileSync(vars.projectDir + '/scripts/research_package.json', 'utf-8');
const prompt = sys + '\n\n---\n\nYour input (research_package.json):\n\n' + researchJson;
return [{ json: { ...vars, claudeBody: JSON.stringify({ prompt }) } }];

const fs   = require('fs');
const inp  = $input.first().json;
const vars = $('Build Script Prompt').first().json;
if (inp.exitCode !== undefined && inp.exitCode !== 0)
  throw new Error('Claude bridge error: ' + inp.error);
const script = (inp.output || '').trim();
if (!script) throw new Error('Script Agent returned empty output');
fs.writeFileSync(vars.projectDir + '/scripts/script.md', script, 'utf-8');
// script.md is on disk — don't carry large string through item data
return [{ json: { topic: vars.topic, audience: vars.audience, runtime: vars.runtime, slug: vars.slug, projectDir: vars.projectDir } }];

const fs   = require('fs');
const vars = $input.first().json;
const sys  = fs.readFileSync('/Users/jneal/n8n_projects/ruins_untold_system_prompts/voice_agent.md', 'utf-8');
const scriptContent = fs.readFileSync(vars.projectDir + '/scripts/script.md', 'utf-8');

// Strip SCRIPT METADATA block then split by section headers
const cleanScript = scriptContent.replace(/## SCRIPT METADATA[\s\S]*$/, '').trim();
const chunks = cleanScript.split(/\n(?=## )/);

const actIdMap = {
  'COLD OPEN':      'cold_open',
  'CHANNEL HOOK':   'hook',
  'CONCLUSION':     'conclusion',
  'CALL TO ACTION': 'cta'
};
const actNumRe = /ACT\s+(\d)/;

const results = [];
for (let i = 0; i < chunks.length; i++) {
  const chunk = chunks[i].trim();
  if (!chunk.startsWith('## ')) continue;
  const nl = chunk.indexOf('\n');
  const header = (nl > -1 ? chunk.substring(0, nl) : chunk).replace(/^## /, '').trim().toUpperCase();
  const sectionText = nl > -1 ? chunk.substring(nl + 1).trim() : '';
  if (!sectionText) continue;

  let actId = null;
  for (const [key, id] of Object.entries(actIdMap)) {
    if (header.includes(key)) { actId = id; break; }
  }
  if (!actId) {
    const nm = header.match(actNumRe);
    if (nm) actId = 'act' + nm[1];
  }
  if (!actId) continue;

  const prompt = sys
    + '\n\nSECTION PROCESSING MODE\n\n'
    + 'Process this ONE section of the script only. Apply Steps 1-6 from your instructions.\n'
    + 'Act ID for this section: ' + actId + '\n'
    + 'Use segment IDs: ' + actId + '_01, ' + actId + '_02, etc. Sequence starts at 1.\n\n'
    + 'IMPORTANT: Return ONLY a raw JSON array of segment objects. '
    + 'No markdown fences, no outer wrapper object, no explanation text.\n\n'
    + 'Section text:\n\n' + sectionText;

  results.push({
    json: {
      ...vars,
      actId,
      sectionIndex: i,
      claudeBody: JSON.stringify({ prompt, max_tokens: 8192, effort: "low" })
    }
  });
}

return results;

const responses    = $input.all();
const sectionItems = $('Split Script by Section').all();

return responses.map((resp, i) => {
  const vars  = sectionItems[i].json;
  const actId = vars.actId;
  const inp   = resp.json;

  if (inp.exitCode !== undefined && inp.exitCode !== 0)
    throw new Error('Voice chunk error [' + actId + ']: ' + inp.error);

  let raw = (inp.output || '').trim();
  const m = raw.match(/```(?:json)?\n?([\s\S]*?)```/);
  if (m) raw = m[1].trim();

  let segments;
  try {
    segments = JSON.parse(raw);
  } catch (e) {
    const s = raw.indexOf('['), en = raw.lastIndexOf(']');
    if (s === -1 || en === -1)
      throw new Error('Cannot parse segments for ' + actId + '. Raw: ' + raw.substring(0, 200));
    segments = JSON.parse(raw.substring(s, en + 1));
  }

  if (!Array.isArray(segments))
    throw new Error('Expected array for ' + actId + ', got ' + typeof segments);

  return { json: { ...vars, segments } };
});

const inp  = $input.first().json;
return inp.voicePackage.segments.map((seg, i) => ({
  json: {
    projectDir:   inp.projectDir,
    voiceId:      inp.voicePackage.voice_id,
    model:        inp.voicePackage.model,
    segmentId:    seg.segment_id,
    sequence:     seg.sequence,
    seqPad:       String(seg.sequence).padStart(3, '0'),
    chunkText:    seg.voice_optimized_text,
    isFirstChunk: i === 0
  }
}));

const item = $input.item.json;
const sd   = $getWorkflowStaticData('global');
const kieInput = { dialogue: [{ text: item.chunkText, voice: item.voiceId }], stability: 0.5 };
if (!item.isFirstChunk && sd.ruinsVoicePrevIds && sd.ruinsVoicePrevIds.length > 0)
  kieInput.previous_request_ids = sd.ruinsVoicePrevIds.slice(-3);
return [{ json: { ...item, kieBody: JSON.stringify({ model: 'elevenlabs/text-to-dialogue-v3', input: kieInput }), includedPrevIds: kieInput.previous_request_ids || [] } }];

const res  = $input.item.json;
const meta = $('Prepare TTS Request').item.json;
if (res.code !== 200) throw new Error('Kie.ai createTask failed (' + meta.segmentId + '): ' + res.msg);
return [{ json: { ...meta, kieTaskId: res.data.taskId } }];

const poll = $input.item.json;
const meta = $('Prepare TTS Request').item.json;
const sd   = $getWorkflowStaticData('global');
let rj = {};
try { rj = JSON.parse(poll.data.resultJson || '{}'); } catch(e) {}
const requestId = rj.request_id || rj.history_item_id || rj.requestId || $('Extract Task ID').item.json.kieTaskId;
if (!sd.ruinsVoicePrevIds) sd.ruinsVoicePrevIds = [];
sd.ruinsVoicePrevIds.push(requestId);
if (sd.ruinsVoicePrevIds.length > 3) sd.ruinsVoicePrevIds = sd.ruinsVoicePrevIds.slice(-3);
const audioUrl = (rj.resultUrls || [])[0] || (poll.data.resultUrls || [])[0] || '';
if (!audioUrl) throw new Error('No audio URL for ' + meta.segmentId + '. state=' + poll.data.state);
return [{ json: { ...meta, kieRequestId: requestId, audioUrl } }];

const { execSync } = require('child_process');
const fs  = require('fs');
const inp = $input.first().json;
const dir = inp.projectDir + '/audio';
const files = fs.readdirSync(dir).filter(f => f.startsWith('seg_') && f.endsWith('.mp3')).sort();
if (files.length === 0) throw new Error('No segment MP3s found in ' + dir);

const silencePath = dir + '/silence.mp3';
execSync('ffmpeg -y -f lavfi -i anullsrc=r=44100:cl=stereo -t 0.625 -q:a 9 -acodec libmp3lame "' + silencePath + '"', { timeout: 30000 });

const concatTxt = dir + '/concat.txt';
const lines = [];
for (let i = 0; i < files.length; i++) {
  lines.push("file '" + dir + '/' + files[i] + "'");
  if (i < files.length - 1) {
    lines.push("file '" + silencePath + "'");
  }
}
fs.writeFileSync(concatTxt, lines.join('\n'), 'utf-8');

const finalPath = dir + '/voiceover_final.mp3';
execSync('ffmpeg -y -f concat -safe 0 -i "' + concatTxt + '" -acodec libmp3lame -ar 44100 -ac 2 -b:a 128k "' + finalPath + '"', { timeout: 300000 });
return [{ json: { ...inp, voiceFinalPath: finalPath } }];

const fs       = require('fs');
const allItems = $input.all();
const vars     = allItems[0].json;

let allSegments = [];
let seq = 1;
for (const item of allItems) {
  for (const seg of (item.json.segments || [])) {
    seg.sequence = seq++;
    allSegments.push(seg);
  }
}

const voicePackage = {
  topic:    vars.topic,
  voice_id: '4YYIPFl9wE5c4L2eu2Gb',
  model:    'eleven_v3',
  stability: 'natural',
  total_word_count: allSegments.reduce((s, seg) => s + (seg.word_count || 0), 0),
  estimated_total_runtime_seconds: allSegments.reduce((s, seg) => s + (seg.estimated_duration_seconds || 0), 0),
  segments: allSegments
};

const pkgPath = vars.projectDir + '/audio/voice_package.json';
fs.writeFileSync(pkgPath, JSON.stringify(voicePackage, null, 2), 'utf-8');

const sd = $getWorkflowStaticData('global');
sd.ruinsVoicePrevIds = [];

return [{ json: { ...vars, voicePackage } }];

const res  = $input.item.json;
const meta = $('Prepare TTS Request').item.json;
const sd   = $getWorkflowStaticData('global');
const taskId = $('Extract Task ID').item.json.kieTaskId;
const state  = (res.data && res.data.state) ? res.data.state : '';

// Terminal error states — fail fast instead of looping forever
const errorStates = ['failed', 'error', 'cancelled', 'expired'];
if (errorStates.includes(state)) {
  delete sd['pollCount_' + taskId];
  throw new Error('Kie.ai task ' + taskId + ' (segment ' + meta.segmentId + ') reached terminal state: ' + state + '. msg=' + ((res.data && res.data.msg) || res.msg || 'none'));
}

// Timeout guard — 36 polls × 10s = 6 minutes max per segment
const counterKey = 'pollCount_' + taskId;
sd[counterKey] = (sd[counterKey] || 0) + 1;
if (sd[counterKey] > 36) {
  delete sd[counterKey];
  throw new Error('Kie.ai task ' + taskId + ' (segment ' + meta.segmentId + ') timed out after 36 polls. Last state: ' + state);
}

if (state === 'success') delete sd[counterKey];
return [{ json: res }];

const item    = $input.item.json;
const meta    = $('Prepare TTS Request').item.json;
const taskId  = $('Extract Task ID').item.json.kieTaskId;
const errMsg  = (item.error && item.error.message) ? item.error.message : (item.error || 'Unknown Kie.ai error');
const resume  = $execution.resumeUrl;

const errInfo = {
  timestamp:  new Date().toISOString(),
  segmentId:  meta.segmentId,
  taskId,
  error:      errMsg,
  actions: {
    retry: resume + '?action=retry',
    skip:  resume + '?action=skip',
    abort: resume + '?action=abort'
  }
};

const fs   = require('fs');
const path = require('path');
const errDir = path.join(meta.projectDir, 'errors');
if (!fs.existsSync(errDir)) fs.mkdirSync(errDir, { recursive: true });
fs.writeFileSync(
  path.join(errDir, 'kie_error_' + meta.segmentId + '.json'),
  JSON.stringify(errInfo, null, 2)
);

console.log('[KIE ERROR] Segment:', meta.segmentId, '| Error:', errMsg);
console.log('[KIE ERROR] Retry :', errInfo.actions.retry);
console.log('[KIE ERROR] Skip  :', errInfo.actions.skip);
console.log('[KIE ERROR] Abort :', errInfo.actions.abort);

return [{ json: { ...meta, kieTaskId: taskId, kieError: errMsg } }];

const body = $input.first().json.body || $input.first().json;
const topic = (body.topic || '').trim();
if (!topic) throw new Error('Webhook payload must include { "topic": "..." }');

// Use pre-created slug/projectDir if provided (promoted from Ideas page), else generate
const ts   = new Date().toISOString().replace(/[^0-9]/g, '').substring(0, 12);
const slug = body.slug || (topic.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/, '').substring(0, 45) + '_' + ts);
const projectDir = body.projectDir || ('/Users/jneal/n8n_projects/' + slug);

// Ensure directories exist (idempotent if already created by web app)
const fs   = require('fs');
const path = require('path');
const dirs = ['scripts','audio','images','videos','clips','music','sfx'];
fs.mkdirSync(projectDir, { recursive: true });
for (const d of dirs) { fs.mkdirSync(path.join(projectDir, d), { recursive: true }); }

// Write full topic so the web UI can display it without slug truncation
fs.writeFileSync(path.join(projectDir, '.topic'), topic, 'utf-8');

return [{ json: {
  topic,
  audience: 'curious history fans, conspiracy-adjacent adults 25-45',
  runtime:  20,
  slug,
  projectDir
} }];
